d=deepcopy(D['decisions']['c0046']);d.update(status='duplicate',society_id=rid,duplicate_of=rid,current_policy_review=True,reassessed_on=DATE,reason='The later supervised Humanoid care baseline repeats the retained provider relationship; Leleyo biological exemption does not establish another automated access regime.',analysis='Guaranteed captive care and controlled games remain under Humanoid supervision. The Two Rivers record keeps its original story period; the later novel is linked without merging plots or treating Leleyo biology as an independently liberated automatic human economy.',follow_up='Resolved provider-model overlap; later-work evidence and biological distinction preserved.');changes.append(change(D,'decisions',d))
